WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating DESC, id) AS row_num FROM suppliers QUALIFY row_num = 1) SELECT CASE WHEN rating >= 3.6 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, SIZE(COLLECT_SET(country)) AS num_countries, STDDEV_SAMP(rating) AS rating_stddev, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(DISTINCT city) AS distinct_cities, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) AS berlin_count FROM latest GROUP BY CASE WHEN rating >= 3.6 THEN 'HIGH' ELSE 'LOW' END
